var checks=new List<string>();void Check(bool ok,string name){if(!ok)throw new Exception("FAIL "+name);checks.Add(name);}
bool Rule(string prefix,params object?[] args){
 var method=typeof(R).GetMethods(BindingFlags.NonPublic|BindingFlags.Static).Single(m=>m.Name.StartsWith(prefix,StringComparison.Ordinal));
 var retired=method.Name.StartsWith("IsLearningV31WalkThroughNativeLocomotionEvidence_recovery_")?new[]{3}:
  method.Name.StartsWith("TryConsumeLearningV429AtomicJumpAdmission_learningV449InsidePhysicalTakeoffHorizon_")?new[]{2,3}:
  method.Name=="UpdateRollingTraversalApproach_traversalGeometryReady_9C18CECF_6"?new[]{1}:
  method.Name.StartsWith("UpdateLearningV349GenericPhysicalProgressWatchdog_movementCountsAsProgress_")||method.Name.StartsWith("TryFinalizeTraversalChainIntermediate_learningV375PersistentRouteGroundSuccessorCandidate_")?new[]{0}:Array.Empty<int>();
 foreach(int index in retired)if(!Equals(args[index],true))throw new Exception("historical fixture supplied a retired inactive version branch");
 if(method.GetParameters().Length!=args.Length-retired.Length)throw new Exception("fixture arity mismatch");
 return (bool)method.Invoke(null,args.Where((value,index)=>!retired.Contains(index)).ToArray())!;
}
